gXl(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u06cc"},
gXk(){return"\u06a4\u06ce \u0642\u06c6\u0646\u0627\u063a\u06ce \u0626\u06d5\u0631\u0634\u06cc\u0641 \u0628\u06a9\u06d5\u06cc\u061f"},
Xj(a){return"\xab"+a+"\xbb \u062f\u06ce \u0698 \u0631\u06ce\u0695\u06d5\u0648\u0627 \u0647\u06d5\u0645\u06cc \u062c\u06c6\u0631\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0648 \u0698 \u062a\u06d5\u062e\u062a\u06cc \u0647\u06ce\u062a\u06d5 \u0644\u0627\u062f\u0627\u0646. \u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u06a9\u06d5\u06a4\u0646 \u0648 \u062f\u06cc\u0631\u06c6\u06a9 \u0646\u0627\u06a4\u06cc \u062f\u067e\u0627\u0631\u06ce\u0632\u0646. \u067e\u0627\u0634\u0627\u0646 \u062f\u0634\u06ce\u06cc \u06a4\u06d5\u06af\u06d5\u0695\u06cc\u0646\u06cc."},
gXi(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u0646"},
gXQ(){return"\u06a4\u06ce \u0642\u06c6\u0646\u0627\u063a\u06ce \u0628 \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc \u0698\u06ce\u0628\u0628\u06d5\u06cc\u061f"},
XP(a){return"\xab"+a+"\xbb \u062f\u06ce \u0628\u06c6 \u0647\u06d5\u0645\u06cc\u0634\u06d5 \u0646\u06d5\u0645\u06cc\u0646\u06cc\u062a. \u0626\u06d5\u06a4\u06d5 \u062a\u0646\u06ce \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a \u0626\u06d5\u06af\u06d5\u0631 \u0686 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0686 \u062c\u0627\u0631\u0627\u0646 \u0628\u06a9\u0627\u0631\u0646\u06d5\u0626\u06cc\u0646\u0627\u0628\u06cc\u062a."},
gFJ(){return"\u0642\u06c6\u0646\u0627\u063a \u0647\u0627\u062a\u06d5 \u0644\u0627\u062f\u0627\u0646."},
gYW(){return"\u0642\u06c6\u0646\u0627\u063a \u0647\u0627\u062a\u06d5 \u06a4\u06d5\u06af\u06d5\u0695\u0627\u0646\u062f\u0646."},
